var response = await client.Email.SendEmailAsync(new Dictionary<string, object?>
{
    ["recipients"] = new List<object?> { "customer@example.com" },
    ["cc"] = new List<object?> { "orders@example.com" },
    ["subject"] = "Your order has shipped", ["htmlContent"] = "<p>Your order is on its way.</p>",
    ["contentType"] = "text/html",
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
Console.WriteLine(body["status"]);
Console.WriteLine(string.Join(", ", (IReadOnlyList<object?>)body["accepted"]!));
Console.WriteLine(string.Join(", ", (IReadOnlyList<object?>)body["cc"]!));
